List<int> unique(List<int> l) {
  List<int> result = [];

  for (int i = 0; i < l.length; i++) {
    bool isUnique = true;

    // Check if the element already exists in the result list.
    for (int j = 0; j < result.length; j++) {
      if (result[j] == l[i]) {
        isUnique = false;
        break;
      }
    }

    // If it's not unique, skip adding it to the result list.
    if (!isUnique) continue;

    // Otherwise, add the element to the result list.
    result.add(l[i]);
  }

  return result;
}

