bool isPrime(int number) {
  if (number <= 1) {
    return false;
  }

  var sqrtNumber = double.sqrt(number);

  for (var i = 2; i <= sqrtNumber; i++) {
    if (number % i == 0) {
      return true; // Divisible by a non-unity factor -> Not prime!
    }
  }

  return false; // No divisors found except unity and itself -> Prime!
