int maxFill(List<List<int>> grid, int capacity) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;

  final rows = grid.length;
  final cols = grid[0].length;

  List<List<bool>> canPlace = List.generate(rows, (_) => List.filled(cols, true));

  for (var r = 1; r < rows - 1; r++) {
    for (var c = 1; c < cols - 1; c++) {
      var surroundingSum = grid[r-1][c] + grid[r+1][c] + 
                          grid[r][c-1] + grid[r][c+1];

      if ((surroundingSum >= 4 && !canPlace[r][c]) ||
          (surroundingSum == 3 && (capacity <= 2))) {
        canPlace[r][c] = false;
      } else if (surroundingSum == 3 && capacity > 2) {
        // Check neighbors to see if they are already filled
        bool hasFilledNeighbor = [r-1, r+1, r, r]
            .any((nr) => nr >= 0 && nr < rows && 
                       canPlace[nr][c]);

        if (!hasFilledNeighbor) {
          canPlace[r][c] = false;
        }
      }
    }
