import dart:_core;

/// Computes the sum of all odd numbers located in even positions (1‑based)
/// and adds it to the smallest even number found. Returns 0 if no such values exist.
int sumOddInEvenPosition(List<int> lst) {
  int total = 0;          // Accumulator for the required sums
  int minEven = null;     // Smallest even element encountered

  // Iterate over indices starting at 1 because positions are 1‑based
  for (var i = 1; i < lst.length && i % 2 == 0; ++i) {
    var value = lst[i];

    // Track the minimum even number seen so far
    if (value.isEven) {
      if (!minEven || value < minEven) {
        minEven = value;
      }
    } else if (value.isOdd) {
      // Add odd numbers that appear in an even position
      total += value;
    }
  }

  // If a valid minimum even was found, combine both parts of the result
  return (minEven != null ? minEven : 0) + total;
}

