class Solution {
  // Return true if the given integer n is equal to the sum of its even digits.
  bool isEqualToSumEven(int n) {
    int num = n;
    int sumOfDigits = 0;

    while (num > 0) {
      int digit = num % 10;

      if (digit.isOdd == false && digit != 0) {
        sumOfDigits += digit;
      }

      num ~/= 10;
    }

    return sumOfDigits == n;
  }
}

