class Calculator {
  static num doAlgebra(List<String> operators, List<int> operands) {
    var stack = <int>[];

    for (var i = 0; i < operators.length; ++i) {
      if (operators[i] == "+") {
        stack.add(stack.removeLast() + stack.removeLast());
      } else if (operators[i] == "-") {
        stack.add(-stack.removeLast() + stack.removeLast());
      } else if (operators[i] == "*") {
        stack.add(stack.removeLast() * stack.removeLast());
      } else if (operators[i] == "//") {
        int firstOperand = stack.removeLast();
        int secondOperand = stack.removeLast();

        double divisionResult = secondOperand / firstOperand; 

        if (!divisionResult.isFinite || !double.parse(divisionResult.toString()).isFinite) {
          throw Exception('Division by zero or non-finite result.');
        }

        stack.add(int.parse(divisionResult.toString()));
      } else if (operators[i] == "**") {
        stack.add(pow(stack.removeLast(), stack.removeLast()).toInt());
      } else {
        print("Invalid operator: $operators");
      }
    }

    return stack.last;
  }
}

